std::string LevelToString(Level level) {
    switch (level) {
        case Level::Debug: return "DEBUG";
        case Level::Info: return "INFO ";
        case Level::Warn: return "WARN ";
        case Level::Error: return "ERROR";
        case Level::Fatal: return "FATAL";
        default: return "UNKNOWN";
    }
}

std::string to_string(Level level) {
    return LevelToString(level);
}

std::ostream& operator<<(std::ostream& os, Level level) {
    os << LevelToString(level);
    return os;
}

Level StringToLevel(const std::string& str) {
    if (str == "DEBUG") return Level::Debug;
    if (str == "INFO ") return Level::Info;
    if (str == "WARN ") return Level::Warn;
    if (str == "ERROR") return Level::Error;
    if (str == "FATAL") return Level::Fatal;
    throw std::runtime_error("Unknown log level: " + str);
}

std::string AppenderTypeToString(AppenderType type) {
    switch (type) {
        case AppenderType::StdOut: return "StdOut";
        case AppenderType::File: return "File";
        default: return "Unknown";
