Logger::Logger(const std::string& name)
    : m_name(name), m_level(Level::Info), m_defaultFormatter(Formatter::Default()), m_capacity(0) {
}

void Logger::Log(const Event& event) {
    if (event.Level() < m_level) return;
    {
        std::lock_guard<std::mutex> lock(m_mutex);
        if (m_capacity > 0 && m_queue.size() >= m_capacity) {
            m_queue.pop();
        }
        m_queue.push(std::make_shared<Event>(event));
    }
    m_cv.notify_one();
}

void Logger::AddAppender(std::shared_ptr<Appender> appender) {
    std::lock_guard<std::mutex> lock(m_mutex);
    m_appenders.push_back(appender);
}

void Logger::RemoveAppender(std::shared_ptr<Appender> appender) {
    std::lock_guard<std::mutex> lock(m_mutex);
    m_appenders.erase(std::remove(m_appenders.begin(), m_appenders.end(), appender), m_appenders.end());
}

void Logger::ClearAppenders() {
    std::lock_guard<std::mutex> lock(m_mutex);
    m_appenders.clear();
}

Level Logger::GetLevel() const { return m_level; }
void Logger::SetLevel(Level level) { m_level = level; }
std::shared_ptr<Formatter> Logger::GetDefaultFormatter() const { return m_defaultFormatter; }
void Logger::SetDefaultFormatter(std::shared_ptr<Formatter> formatter) { m_defaultFormatter = formatter; }
const std::string& Logger::Name() const { return m_name; }
size_t Logger::Capacity() const { return m_capacity; }

YAML::Node Logger::ToYamlString() const {
    YAML::Node node;
    node["name"] = m_name;
    node["level"] = LevelToString(m_level);
    YAML::Node appenders;
    for (const auto& appender : m_appenders) {
        appenders.push_back(appender->ToYamlString());
    }
    node["appenders"] = appenders;
    return node;
}

void Logger::ProcessLogs() {
    while (m_running) {
        std::unique_lock<std::mutex> lock(m_mutex);
        m_cv.wait(lock, [this] { return !m_queue.empty() || !m_running; });
        if (!m_running && m_queue.empty()) break;
        while (!m_queue.empty()) {
            auto event = m_queue.front();
            m_queue.pop();
            lock.unlock();
            for (const auto& appender : m_appenders) {
                appender->Log(*event);
            }
            lock.lock();
        }
    }
}

EventWriter::EventWriter(std::shared_ptr<Logger> logger, Level level)
    : m_logger(logger), m_level(level) {
    auto now = std::chrono::system_clock::now();
    auto time = std::chrono::system_clock::to_time_t(now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&time));
    m_event = Event::Create(level, "unknown", 0, "unknown", std::string(buffer) + " ");
}

std::ostringstream& EventWriter::MessageStream() { return m_event->MessageStream(); }

Manager& Manager::Instance() {
    static Manager instance;
    return instance;
}

std::shared_ptr<Logger> Manager::FindLogger(const std::string& name) {
    std::lock_guard<std::mutex> lock(m_mutex);
    for (const auto& logger : m_loggers) {
        if (logger->Name() == name) return logger;
    }
    return nullptr;
}

void Manager::RemoveLogger(const std::string& name) {
    std::lock_guard<std::mutex> lock(m_mutex);
    m_loggers.erase(std::remove_if(m_loggers.begin(), m_loggers.end(), [&name](const auto& logger) { return logger->Name() == name; }), m_loggers.end());
}

YAML::Node Manager::ToYamlString() const {
    YAML::Node node;
    YAML::Node loggers;
    for (const auto& logger : m_loggers) {
        loggers.push_back(logger->ToYamlString());
    }
    node["loggers"] = loggers;
    return node;
}

void Manager::InitConfig(const YAML::Node& config) {
    // Implementation would parse the YAML config and initialize loggers/appenders accordingly
}

Manager::Manager() {}

void Log(Level level, const char* fileName, int lineNum, const char* funcName, const std::string& message) {
    auto event = Event::Create(level, fileName, lineNum, funcName, message);
    RootLogger().Log(*event);
}

std::ostream& operator<<(std::ostream& os, EventWriter&& writer) {
    os << writer.MessageStream().str();
    return os;
}

Manager& RootManager() { return Manager::Instance(); }
Logger& RootLogger() { static Logger root("root"); return root; }
std::shared_ptr<Logger> FindLogger(const std::string& name) { return RootManager().FindLogger(name); }
}

