bool operator==(const RawField& lhs, const RawField& rhs) {
    return lhs.tag == rhs.tag && lhs.content == rhs.content;
}

bool operator!=(const RawField& lhs, const RawField& rhs) {
    return !(lhs == rhs);
}

std::vector<RawField> ParsePattern(const std::string& pattern) {
    std::vector<RawField> fields;
    size_t pos = 0;
    while (pos < pattern.size()) {
        if (pattern[pos] == '%') {
            if (pos + 1 >= pattern.size()) break;
            char tag = pattern[++pos];
            std::string content;
            if (tag == 'd' || tag == 'p' || tag == 't' || tag == 'm' || tag == 'f' || tag == 'l' || tag == 'n') {
                fields.push_back({std::string(1, tag), ""});
            } else if (tag == '\\') {
                if (pos + 1 >= pattern.size()) break;
                char next = pattern[++pos];
                if (next == 'n' || next == 't') {
                    fields.push_back({std::string(1, next), ""});
                } else {
                    content += next;
                }
            } else {
                content += tag;
            }
        } else {
            std::string content;
            while (pos < pattern.size() && pattern[pos] != '%') {
                content += pattern[pos++];
            }
            if (!content.empty()) {
                fields.push_back({"raw", content});
            }
        }
    }
    return fields;
}

std::vector<std::shared_ptr<Formatter::Field>> RawFieldsToFormatFields(const std::vector<RawField>& rawFields) {
    std::vector<std::shared_ptr<Formatter::Field>> fields;
    for (const auto& field : rawFields) {
        if (field.tag == "m") {
            fields.push_back(std::make_shared<Message>());
        } else if (field.tag == "p") {
            fields.push_back(std::make_shared<Level>());
        } else if (field.tag == "t") {
            fields.push_back(std::make_shared<ThreadId>());
        } else if (field.tag == "d") {
            fields.push_back(std::make_shared<DateTime>());
        } else if (field.tag == "f") {
            fields.push_back(std::make_shared<FileName>());
        } else if (field.tag == "l") {
            fields.push_back(std::make_shared<LineNum>());
        } else if (field.tag == "n") {
            fields.push_back(std::make_shared<NewLine>());
        } else if (field.tag == "\t") {
            fields.push_back(std::make_shared<Tab>());
        } else if (field.tag == "raw") {
            fields.push_back(std::make_shared<RawString>(field.content));
        }
    }
    return fields;
}
}

